'use client';
import { useEffect, useId, useRef, useState, type CSSProperties, type PointerEvent, type ReactNode } from 'react';
import { useStudioMotion } from '../../motion';
import type { EffectProps } from '../../types';
import styles from './styles.module.css';

type Params = { radius: number; intensity: number; surface: boolean; color: string; follow: string };

const icon = (d: ReactNode) => (
  <svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false">{d}</svg>
);

/** Sample modules for an invented writing tool. */
const MODULES: readonly { id: string; name: string; text: string; glyph: ReactNode }[] = [
  { id: 'offline', name: 'Offline drafts', text: 'Write without a connection; changes merge when you are back online.', glyph: icon(<><path d="M7 18h10a4 4 0 0 0 .6-8 6 6 0 0 0-11.4 1.5A3.3 3.3 0 0 0 7 18z" /><path d="M4 4l16 16" /></>) },
  { id: 'history', name: 'Version history', text: 'Every save is kept, with named restore points you can compare side by side.', glyph: icon(<><circle cx="12" cy="12" r="8" /><path d="M12 8v4l3 2" /></>) },
  { id: 'cursors', name: 'Shared cursors', text: 'See who is reading, who is editing and who has just stepped away.', glyph: icon(<><path d="M5 4l5 14 2-6 6-2z" /><path d="M15 15l4 4" /></>) },
  { id: 'audit', name: 'Audit log', text: 'A plain-language record of who changed what, and when they did it.', glyph: icon(<><path d="M8 6h11M8 12h11M8 18h11" /><circle cx="4.5" cy="6" r="1" /><circle cx="4.5" cy="12" r="1" /><circle cx="4.5" cy="18" r="1" /></>) },
  { id: 'roles', name: 'Granular roles', text: 'Viewer, commenter, editor and owner, set per page or for a whole space.', glyph: icon(<><circle cx="8" cy="15" r="4" /><path d="M11 12l8-8M16 7l2 2M14 9l2 2" /></>) },
  { id: 'export', name: 'Export anywhere', text: 'PDF, Markdown or a zipped folder of plain files, whenever you like.', glyph: icon(<><path d="M12 3v12M7 8l5-5 5 5" /><path d="M5 14v5h14v-5" /></>) },
];
const SPOT: Record<string, string> = { signal: 'var(--s3-signal, #bf2f09)', ink: 'var(--s3-ink, #11110f)', accent: 'var(--s3-accent, #bf2f09)' };

export default function SpotlightBorderCard({ params }: EffectProps<Params>) {
  const { reduced } = useStudioMotion();
  const uid = useId();
  const grid = useRef<HTMLUListElement>(null);
  const frame = useRef(0);
  const point = useRef<{ x: number; y: number } | null>(null);
  const [selected, setSelected] = useState<ReadonlySet<string>>(() => new Set(['history', 'roles']));

  useEffect(() => () => cancelAnimationFrame(frame.current), []);
  useEffect(() => { if (reduced) delete grid.current?.dataset.lit; }, [reduced]);

  // The one pointer listener: batch to a frame, read every card rect first, then write.
  const paint = () => {
    frame.current = 0;
    const g = grid.current;
    const p = point.current;
    if (!g || !p) return;
    const cards = [...g.querySelectorAll<HTMLElement>('[data-card]')];
    const rects = cards.map((c) => c.getBoundingClientRect());
    cards.forEach((c, i) => {
      c.style.setProperty('--sbc-x', `${(p.x - rects[i].left).toFixed(1)}px`);
      c.style.setProperty('--sbc-y', `${(p.y - rects[i].top).toFixed(1)}px`);
    });
    g.dataset.lit = '';
  };
  const onMove = (e: PointerEvent<HTMLUListElement>) => {
    if (reduced || e.pointerType === 'touch') return;
    point.current = { x: e.clientX, y: e.clientY };
    if (!frame.current) frame.current = requestAnimationFrame(paint);
  };
  const onLeave = () => {
    cancelAnimationFrame(frame.current);
    frame.current = 0;
    if (grid.current) delete grid.current.dataset.lit;
  };

  const toggle = (id: string) => setSelected((s) => {
    const n = new Set(s);
    if (n.has(id)) n.delete(id); else n.add(id);
    return n;
  });

  return (
    <div
      className={styles.root}
      data-reduced={reduced || undefined}
      data-follow={params.follow === 'instant' ? 'instant' : 'smooth'}
      data-surface={params.surface || undefined}
      style={{ '--sbc-r': `${params.radius}px`, '--sbc-a': `${params.intensity}%`, '--sbc-spot': SPOT[params.color] ?? SPOT.signal } as CSSProperties}
    >
      <header className={styles.head}>
        <div>
          <p className={styles.eyebrow}>Ledgerline · workspace setup</p>
          <h3 className={styles.title} id={`${uid}title`}>Choose your modules</h3>
        </div>
        <p className={styles.status} role="status">{selected.size} of {MODULES.length} added · sample</p>
      </header>
      <ul ref={grid} className={styles.grid} aria-labelledby={`${uid}title`} onPointerMove={onMove} onPointerLeave={onLeave}>
        {MODULES.map((m) => {
          const on = selected.has(m.id);
          return (
            <li key={m.id} className={styles.card} data-card data-on={on || undefined}>
              <span className={styles.glyph}>{m.glyph}</span>
              <h4 className={styles.name}>
                <button type="button" className={styles.toggle} aria-pressed={on} aria-describedby={`${uid}${m.id}`} onClick={() => toggle(m.id)}>
                  {m.name}
                </button>
              </h4>
              <p id={`${uid}${m.id}`} className={styles.text}>{m.text}</p>
              <span className={styles.state} aria-hidden="true">
                <span className={styles.tick}>
                  <svg viewBox="0 0 16 16" width="12" height="12"><path d={on ? 'M3.5 8.5l3 3 6-7' : 'M8 3.5v9M3.5 8h9'} fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" /></svg>
                </span>
                {on ? 'Added' : 'Add'}
              </span>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

/* Registered so the light can trail the pointer with a plain CSS transition (smooth follow). */
@property --sbc-x { syntax: '<length>'; inherits: true; initial-value: -1000px; }
@property --sbc-y { syntax: '<length>'; inherits: true; initial-value: -1000px; }

.root {
  --sbc-r: 260px;
  --sbc-a: 75%;
  --sbc-spot: var(--s3-signal, #bf2f09);
  container-type: inline-size;
  box-sizing: border-box;
  width: min(100% - 2rem, 60rem);
  margin: clamp(1rem, 3cqi, 2rem) auto;
  display: grid;
  gap: 1rem;
  color: var(--s3-ink, #11110f);
  font-family: var(--s3-font-text, ui-sans-serif, system-ui, sans-serif);
}
.head {
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  justify-content: space-between;
  gap: 0.4rem 1.5rem;
  padding-bottom: 0.8rem;
  border-bottom: 1px solid var(--s3-line, #11110f24);
}
.eyebrow, .status, .state {
  margin: 0;
  font-family: var(--s3-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-variant-numeric: tabular-nums;
  color: var(--s3-ink-muted, #5c5a52);
}
.eyebrow { margin-bottom: 0.4rem; }
.title {
  margin: 0;
  font-family: var(--s3-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: clamp(1.5rem, 5cqi, 2.25rem);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.035em;
}

.grid {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(15rem, 100%), 1fr));
  gap: 12px;
}
.card {
  position: relative;
  isolation: isolate;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto auto 1fr auto;
  gap: 0.45rem;
  padding: 1.1rem 1.1rem 1rem;
  border-radius: 16px;
  background: var(--s3-surface-2, #e9e5da);
  box-shadow: inset 0 0 0 1px var(--s3-line, #11110f24);
}
.root[data-follow='smooth'] .card { transition: --sbc-x 140ms linear, --sbc-y 140ms linear; }
.card[data-on] { box-shadow: inset 0 0 0 1px var(--s3-line-strong, #11110f); }

/* Light layers: both read the card's local pointer position. */
.card::before, .card::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  opacity: 0;
  transition: opacity var(--s3-duration-base, 240ms) var(--s3-ease-standard, ease);
}
/* 1px ring: the radial light is masked down to the border (content box excluded). */
.card::before {
  z-index: 1;
  padding: 1px;
  background: radial-gradient(var(--sbc-r) circle at var(--sbc-x) var(--sbc-y), color-mix(in oklab, var(--sbc-spot) var(--sbc-a), transparent), transparent 70%);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0);
}
/* Faint wash on the surface, under the text. */
.card::after {
  z-index: -1;
  background: radial-gradient(var(--sbc-r) circle at var(--sbc-x) var(--sbc-y), color-mix(in oklab, var(--sbc-spot) 9%, transparent), transparent 65%);
}
.grid[data-lit] .card::before { opacity: 1; }
.root[data-surface] .grid[data-lit] .card::after { opacity: 1; }

/* Keyboard focus lights the focused card on its own, wherever the pointer is. */
.card:has(.toggle:focus-visible) { outline: 2px solid var(--s3-focus, #1d4ed8); outline-offset: 3px; }
.card:has(.toggle:focus-visible)::before {
  opacity: 1;
  background: radial-gradient(140% 120% at 50% 0%, var(--sbc-spot), color-mix(in oklab, var(--sbc-spot) 35%, transparent) 75%);
}
.root[data-surface] .card:has(.toggle:focus-visible)::after {
  opacity: 1;
  background: radial-gradient(120% 90% at 50% 0%, color-mix(in oklab, var(--sbc-spot) 10%, transparent), transparent 70%);
}

.glyph {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  margin-bottom: 0.35rem;
  border-radius: 11px;
  background: var(--s3-surface, #fbf9f4);
  box-shadow: inset 0 0 0 1px var(--s3-line, #11110f24);
  color: var(--s3-ink, #11110f);
}
.name { margin: 0; font-size: 1rem; font-weight: 650; letter-spacing: -0.015em; }
/* The button is the card's single control; its ::after stretches over the card. */
.toggle {
  all: unset;
  cursor: pointer;
}
.toggle::after { content: ''; position: absolute; inset: 0; z-index: 2; border-radius: 16px; }
.toggle:focus-visible { outline: none; }
.text { margin: 0; font-size: 0.875rem; line-height: 1.5; color: var(--s3-ink-muted, #5c5a52); text-wrap: pretty; }
.state { display: inline-flex; align-items: center; gap: 0.45rem; margin-top: 0.4rem; }
.tick {
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  box-shadow: inset 0 0 0 1px var(--s3-line-strong, #11110f);
  color: var(--s3-ink, #11110f);
}
.card[data-on] .state { color: var(--s3-ink, #11110f); }
.card[data-on] .tick { background: var(--s3-ink, #11110f); color: var(--s3-surface, #fbf9f4); }

@container (max-width: 480px) {
  .card { grid-template-columns: auto minmax(0, 1fr); grid-template-rows: auto auto auto; column-gap: 0.85rem; padding: 0.9rem; }
  .glyph { grid-row: 1 / span 3; margin: 0; }
  .state { margin-top: 0.15rem; }
}

/* Reduced motion: no travelling light, a static lit border on hover instead. */
.root[data-reduced] .card, .root[data-reduced] .card::before, .root[data-reduced] .card::after { transition: none; }
.root[data-reduced] .card:hover::before { opacity: 1; background: color-mix(in oklab, var(--sbc-spot) 70%, transparent); }
@media (prefers-reduced-motion: reduce) {
  .card, .card::before, .card::after { transition: none; }
}
